import{_ as i,I as s,c as o,o as a,a3 as t,b as c,w as n,a as l,J as p,a4 as d}from"./chunks/framework.MI-M1z4O.js";const A=JSON.parse('{"title":"Enterprise Adoption FAQ & Private AI Security","description":"Frequently asked questions (FAQ) for enterprise customers evaluating SyncVerse, including on-premises air-gapped private AI deployment and integration guides for existing CI/CD and Git systems.","frontmatter":{"title":"Enterprise Adoption FAQ & Private AI Security","sidebarTitle":"Enterprise FAQ","description":"Frequently asked questions (FAQ) for enterprise customers evaluating SyncVerse, including on-premises air-gapped private AI deployment and integration guides for existing CI/CD and Git systems.","head":[["meta",{"name":"keywords","content":"SyncVerse, Enterprise FAQ, On-Premises, Private AI, Air-Gapped, Ollama, vLLM, Git Integration, Jenkins Integration, Kubernetes"}],["meta",{"property":"og:title","content":"SyncVerse: Enterprise Adoption FAQ & Private AI Security"}],["meta",{"property":"og:description","content":"Core enterprise adoption FAQ from on-premises deployment to existing system integration"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncverse/enterprise-faq"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncverse/enterprise-faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncverse/enterprise-faq"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncverse/enterprise-faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncverse/enterprise-faq"}]],"sort":10},"headers":[],"relativePath":"en/syncverse/enterprise-faq.md","filePath":"en/syncverse/enterprise-faq.md","lastUpdated":1795293539000}'),h={name:"en/syncverse/enterprise-faq.md"};function g(u,e,m,y,f,v){const r=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="enterprise-adoption-faq-private-ai-security" tabindex="-1">Enterprise Adoption FAQ &amp; Private AI Security <a class="header-anchor" href="#enterprise-adoption-faq-private-ai-security" aria-label="Permalink to “Enterprise Adoption FAQ &amp; Private AI Security”">​</a></h1><p>This page compiles frequently asked questions and technical answers from enterprise architects and security officers evaluating SyncVerse for production environments.</p><hr><h2 id="_1-security-private-ai-environment" tabindex="-1">1. Security &amp; Private AI Environment <a class="header-anchor" href="#_1-security-private-ai-environment" aria-label="Permalink to “1. Security &amp; Private AI Environment”">​</a></h2><h3 id="q1-can-syncverse-be-configured-so-that-internal-source-code-and-data-are-never-sent-to-external-ai-vendors-such-as-openai" tabindex="-1">Q1. Can SyncVerse be configured so that internal source code and data are never sent to external AI vendors (such as OpenAI)? <a class="header-anchor" href="#q1-can-syncverse-be-configured-so-that-internal-source-code-and-data-are-never-sent-to-external-ai-vendors-such-as-openai" aria-label="Permalink to “Q1. Can SyncVerse be configured so that internal source code and data are never sent to external AI vendors (such as OpenAI)?”">​</a></h3><blockquote><p><strong>A. Yes, air-gapped and on-premises deployments are fully supported.</strong><br> SyncVerse integrates with self-hosted open-source LLMs (vLLM, Ollama, internally fine-tuned Llama 3 / Solar-Pro, etc.) and internal GPU servers. Even when using commercial cloud LLMs, data is protected through <strong>automatic PII masking filters</strong> and <strong>enterprise Zero Data Retention endpoints</strong>.</p></blockquote><h3 id="q2-is-there-any-risk-of-ai-accidentally-damaging-a-production-database" tabindex="-1">Q2. Is there any risk of AI accidentally damaging a production database? <a class="header-anchor" href="#q2-is-there-any-risk-of-ai-accidentally-damaging-a-production-database" aria-label="Permalink to “Q2. Is there any risk of AI accidentally damaging a production database?”">​</a></h3><blockquote><p><strong>A. No, destructive changes are blocked preemptively by HITL (Human-In-The-Loop) governance.</strong><br> All schema-altering DDL statements (such as <code>ALTER TABLE</code> or <code>DROP</code>) and production deployments cannot be executed autonomously by agents alone; they require explicit approval from a system architect along with 2FA verification.</p></blockquote><hr><h2 id="_2-existing-infrastructure-system-integration" tabindex="-1">2. Existing Infrastructure &amp; System Integration <a class="header-anchor" href="#_2-existing-infrastructure-system-integration" aria-label="Permalink to “2. Existing Infrastructure &amp; System Integration”">​</a></h2><h3 id="q3-can-syncverse-integrate-with-our-existing-git-repositories-ci-cd-pipelines-and-internal-messaging-tools" tabindex="-1">Q3. Can SyncVerse integrate with our existing Git repositories, CI/CD pipelines, and internal messaging tools? <a class="header-anchor" href="#q3-can-syncverse-integrate-with-our-existing-git-repositories-ci-cd-pipelines-and-internal-messaging-tools" aria-label="Permalink to “Q3. Can SyncVerse integrate with our existing Git repositories, CI/CD pipelines, and internal messaging tools?”">​</a></h3><blockquote><p><strong>A. Yes, it provides standard integration interfaces for enterprise infrastructure.</strong></p><ul><li><strong>Source Control</strong>: GitHub, GitLab, Bitbucket (working branch creation, PR submission, code diff inspection)</li><li><strong>CI/CD Pipelines</strong>: Jenkins, GitHub Actions, GitLab CI, ArgoCD</li><li><strong>Container Orchestration</strong>: Kubernetes, Docker Compose</li><li><strong>Collaboration Tools</strong>: Slack, Microsoft Teams, Jira, Dooray (approval request notifications and status checks)</li></ul></blockquote>',12)),(a(),c(d,null,{default:n(()=>[p(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Git%5B%22Git%20%2F%20GitLab%3Cbr%2F%3E(PR%20%26%20Diff)%22%5D%20%3C--%3E%20Verse%5B%22SyncVerse%20Control%20Tower%22%5D%0A%20%20%20%20CI%5B%22Jenkins%20%2F%20K8s%3Cbr%2F%3E(Build%20%26%20Deploy)%22%5D%20%3C--%3E%20Verse%0A%20%20%20%20Slack%5B%22Slack%20%2F%20Teams%3Cbr%2F%3E(Approval%20Alerts)%22%5D%20%3C--%3E%20Verse%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="q4-does-syncverse-support-legacy-systems-written-in-languages-other-than-java-spring-boot" tabindex="-1">Q4. Does SyncVerse support legacy systems written in languages other than Java Spring Boot? <a class="header-anchor" href="#q4-does-syncverse-support-legacy-systems-written-in-languages-other-than-java-spring-boot" aria-label="Permalink to “Q4. Does SyncVerse support legacy systems written in languages other than Java Spring Boot?”">​</a></h3><blockquote><p><strong>A. Yes, it does.</strong><br> Because SyncVerse communicates over the standard <strong>Model Context Protocol (MCP)</strong> and <strong>REST/JSON-RPC</strong>, microservices written in any language—such as Python (FastAPI), Node.js (NestJS), Go, or C#—can be integrated into the Control Tower by attaching a standard MCP Server wrapper.</p></blockquote><hr><h2 id="_3-adoption-process-poc-roadmap" tabindex="-1">3. Adoption Process &amp; PoC Roadmap <a class="header-anchor" href="#_3-adoption-process-poc-roadmap" aria-label="Permalink to “3. Adoption Process &amp; PoC Roadmap”">​</a></h2><h3 id="phase-1-preparation-poc-2–4-weeks" tabindex="-1">Phase 1: Preparation &amp; PoC (2–4 Weeks) <a class="header-anchor" href="#phase-1-preparation-poc-2–4-weeks" aria-label="Permalink to “Phase 1: Preparation &amp; PoC (2–4 Weeks)”">​</a></h3><ul><li>Select one target domain service and connect it to the SyncVerse Control Tower</li><li>Register the target service&#39;s Git repository and MCP servers for <code>SyncBoot</code>, <code>SyncCMS</code>, and <code>SyncETA</code> agents</li><li>Test intent routing accuracy and natural language command execution</li></ul><h3 id="phase-2-pilot-operation-4–8-weeks" tabindex="-1">Phase 2: Pilot Operation (4–8 Weeks) <a class="header-anchor" href="#phase-2-pilot-operation-4–8-weeks" aria-label="Permalink to “Phase 2: Pilot Operation (4–8 Weeks)”">​</a></h3><ul><li>Operate autonomous QA and self-healing pipelines in Dev/Stage environments</li><li>Enable the architect HITL approval console and measure reductions in feature delivery lead time (TTM)</li></ul><h3 id="phase-3-enterprise-wide-ai-dlc-expansion-ongoing" tabindex="-1">Phase 3: Enterprise-Wide AI DLC Expansion (Ongoing) <a class="header-anchor" href="#phase-3-enterprise-wide-ai-dlc-expansion-ongoing" aria-label="Permalink to “Phase 3: Enterprise-Wide AI DLC Expansion (Ongoing)”">​</a></h3><ul><li>Expand Control Tower coverage across all enterprise microservices</li><li>Connect business data directly to development execution through <code>SyncInsight</code> integration</li></ul><hr><h2 id="_4-licensing-technical-support" tabindex="-1">4. Licensing &amp; Technical Support <a class="header-anchor" href="#_4-licensing-technical-support" aria-label="Permalink to “4. Licensing &amp; Technical Support”">​</a></h2><p>SyncVerse is available in both an Open-Source Community Edition and an Enterprise Edition.</p><ul><li><strong>Adoption Inquiries &amp; PoC Support</strong>: <code>poh@empasy.com</code></li><li><strong>Official Technical Support Portal</strong>: <a href="https://doc.empasy.com" target="_blank" rel="noreferrer">https://doc.empasy.com</a></li></ul>',14))])}const k=i(h,[["render",g]]);export{A as __pageData,k as default};
